"""Full evaluation pipeline: one command, offline, $0, every number generated by code.

    python -m evals.pipeline

Runs, in order, and records each step's exit code and time:
  1. ruff (lint)
  2. pytest: every unit, regression, ACID and scenario test (junit XML, counted per file)
  3. python -m evals.run: the 44 scripted scenarios with 10 safety rules each
     (writes docs/eval_results.md, the brief's eval table)
  4. python -m evals.live --replay: the 64 recorded live Gemini cases, re-scored offline
  5. python -m evals.redteam --agent --replay: blind red-team rounds + recorded agent replies

Then it checks the brief (Orange_Engineering_Assignment.pdf) requirement by requirement
against those results and the repo, and writes docs/EVALUATION_REPORT.md and
evals/pipeline_results.json. The LLM judge (python -m evals.judge) calls a model, so the
pipeline doesn't run it; it reports the judge's saved results with their date instead.
Do not edit the generated report by hand.
"""

from __future__ import annotations

import json
import re
import subprocess
import sys
import time
import xml.etree.ElementTree as ET
from collections import Counter
from datetime import datetime
from pathlib import Path
from statistics import mean
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
REPORT = ROOT / "docs" / "EVALUATION_REPORT.md"
JSON_OUT = ROOT / "evals" / "pipeline_results.json"
JUNIT = ROOT / "var" / "pytest-junit.xml"


def run(name: str, args: list[str]) -> dict[str, Any]:
    t0 = time.perf_counter()
    p = subprocess.run([sys.executable, *args], cwd=ROOT, capture_output=True, text=True)
    out = (p.stdout + p.stderr).strip().splitlines()
    step = {"step": name, "command": " ".join(["python", *args]), "exit": p.returncode,
            "seconds": round(time.perf_counter() - t0, 1), "tail": out[-3:]}
    print(f"{'ok ' if p.returncode == 0 else 'FAIL'} {name} ({step['seconds']}s)")
    return step


def pytest_counts() -> dict[str, Any]:
    root = ET.parse(JUNIT).getroot()
    suites = root.findall("testsuite") or [root]
    per_file: Counter = Counter()
    failed: list[str] = []
    for case in (c for s in suites for c in s.iter("testcase")):
        f = (case.get("classname") or "").split(".")
        name = f[1] if len(f) > 1 else f[0]
        per_file[name] += 1
        if case.find("failure") is not None or case.find("error") is not None:
            failed.append(f"{name}::{case.get('name')}")
    return {"total": sum(per_file.values()), "failed": failed, "per_file": dict(per_file)}


def load(path: str) -> Any:
    p = ROOT / path
    return json.loads(p.read_text()) if p.exists() else None


# Each brief requirement -> the scenarios and test files that prove it. Status is computed:
# every listed scenario passed and every listed test file ran with no failures.
BRIEF: list[tuple[str, str, list[str], list[str]]] = [
    ("2. Tools", "8 mock tools with the contract's inputs, outputs and failure modes "
     "(70/15/15 book, half of timeouts booked, hold_expired, 503-then-retry cancel, "
     "slot_conflict, injection review); seeded and reproducible",
     [], ["test_mocks", "test_contract_boundary"]),
    ("3. Conversation and state", "Ask only for missing details, never re-ask, keep "
     "unrelated context on a correction, explicit workflow",
     ["S01", "S02", "S03", "S20", "S43"], ["test_errands", "test_walkthrough_fixes"]),
    ("3. Approval enforcement", "Explicit confirmation of the exact action, enforced by code; "
     "a material change invalidates approval",
     ["S04", "S06", "S07", "S08", "S14", "S32"], ["test_core", "test_users"]),
    ("3. Bounded execution", "Hard limits on model turns, tool calls and time; every exit "
     "has a clear outcome; exhausted retries and tool errors handled",
     ["S17", "S28", "S29", "S30", "S31"], []),
    ("3. Booking correctness", "No duplicates across repeated confirmations, retries and "
     "restarts; timeouts resolved by the source of truth; success only when verified",
     ["S09", "S10", "S11", "S12", "S13", "S14", "S15"], ["test_acid"]),
    ("3. Untrusted tool output", "Reviews are data; injection can't change intent, "
     "permissions or approval", ["S05", "S36", "S44"], ["test_guard"]),
    ("3. Persistent memory", "Preferences across sessions; inspect, correct, forget; "
     "explicit vs inferred", ["S21", "S22", "S23", "S24", "S25"], ["test_memory_tools"]),
    ("3. Observability", "Per-run trace: transitions, model calls, tool names and "
     "arguments, sanitised results, latency, tokens, cost", ["S09", "S33"], []),
    ("3. Evaluation", "≥20 automated scenarios asserting outcomes and invariants, covering "
     "every listed category", [], []),
    ("3. Proactive follow-up", "Provider cancellation detected unprompted, replacement "
     "within preferences, fresh approval before rebooking", ["S26"], ["test_errands"]),
    ("3. Context management", "≥50 seeded memories and a long history; fixed token cap; "
     "only relevant current preferences; logged and proven in tests", ["S27"],
     ["test_context"]),
    ("4. Real LLM, offline evals", "A real LLM drives tool calls; automated evals run "
     "offline against a scripted or recorded model", ["S33"], ["test_live_replay"]),
    ("4. More than one agent", "A second agent where it solves a problem better "
     "(tool-less review reader)", ["S05"], []),
]

# The brief's evaluation list -> scenario ids that cover each item.
CATEGORIES = {
    "adversarial input": ["S04", "S06"], "prompt injection": ["S05"],
    "changed price/slot after approval": ["S08", "S32"],
    "timeout after possible success": ["S09"], "slot conflict": ["S19"],
    "repeated confirmation": ["S14"], "memory correction/forgetting": ["S22", "S23"],
    "restart mid-booking": ["S15"], "proactive cancellation": ["S26"],
    "context budget": ["S27"], "limit exhaustion": ["S28", "S29", "S30"],
    "tool failures": ["S17", "S31"],
}


def deliverables() -> list[dict[str, Any]]:
    design = (ROOT / "docs" / "DESIGN.md").read_text()
    words = len(design.split())
    bugs = len(re.findall(r"^#{2,3} \d+\.", (ROOT / "docs" / "BUGS.md").read_text(), re.M))
    trace = ROOT / "traces" / "committed" / "live_timeout_after_success.jsonl"
    events = [json.loads(x) for x in trace.read_text().splitlines()] if trace.exists() else []
    timed_out = any(e.get("type") == "tool_call" and e.get("tool") == "book"
                    and (e.get("error") == "timeout"
                         or "timeout" in json.dumps(e.get("result") or ""))
                    for e in events)
    verified = any(e.get("type") == "action_confirmed" for e in events)
    table = (ROOT / "docs" / "eval_results.md").read_text()
    readme = (ROOT / "README.md").read_text()
    links = re.findall(r"https?://(?:www\.)?(?:youtu\.be|youtube\.com|loom\.com)/\S+", readme)
    demo_link = links[0].rstrip(")|") if links else ""
    transcripts = sorted(p.name for p in (ROOT / "transcripts").glob("*.md")
                         if p.name != "README.md")
    return [
        {"item": "Git repo: implementation, mocks, tests, README",
         "ok": (ROOT / "README.md").exists() and (ROOT / "src" / "errand_agent" / "mocks").is_dir(),
         "evidence": "README.md, src/errand_agent/, src/errand_agent/mocks/, tests/"},
        {"item": "Design note, max 1 page",
         "ok": words <= 850 and all(k in design for k in (
             "State model", "Approval enforcement", "Idempotency", "Memory", "observability")),
         "evidence": f"docs/DESIGN.md: {words} words; state model, approval, idempotency, "
                     "memory, observability, trade-offs, trace excerpt"},
        {"item": "Eval table generated by the test run",
         "ok": "Do not edit by hand" in table and "| S01 |" in table,
         "evidence": "docs/eval_results.md (written by python -m evals.run)"},
        {"item": "Three real bugs with regression tests", "ok": bugs >= 3,
         "evidence": f"docs/BUGS.md: {bugs} bugs, each with its regression test"},
        {"item": "End-to-end trace with timeout-after-success",
         "ok": timed_out and verified and "Trace excerpt" in design,
         "evidence": f"{trace.relative_to(ROOT)}: {len(events)} events, book timed out, "
                     "verified via get_booking_status; annotated in DESIGN.md"},
        {"item": "Recorded demo, 3–5 min",
         "ok": True if demo_link else None,
         "evidence": f"README.md links the recording: {demo_link}" if demo_link
                     else "manual: video not linked in README.md yet (script: docs/DEMO.md)"},
        {"item": "AI coding-assistant transcripts", "ok": bool(transcripts),
         "evidence": f"transcripts/: {len(transcripts)} Claude Code sessions, indexed in "
                     "transcripts/README.md"},
    ]


def main() -> int:
    JUNIT.parent.mkdir(exist_ok=True)
    steps = [
        run("lint (ruff)", ["-m", "ruff", "check", "."]),
        run("tests (pytest)", ["-m", "pytest", "-q", "-p", "no:cacheprovider",
                               f"--junitxml={JUNIT.relative_to(ROOT)}"]),
        run("scenarios (evals.run)", ["-m", "evals.run"]),
        run("live cases, replayed (evals.live --replay)", ["-m", "evals.live", "--replay"]),
        run("red team, replayed (evals.redteam --agent --replay)",
            ["-m", "evals.redteam", "--agent", "--replay"]),
    ]
    tests = pytest_counts()
    scen = load("evals/results.json") or []
    by_id = {s["id"]: s for s in scen}
    live = (load("evals/live_results.json") or {}).get("results", [])
    red = load("evals/redteam_results.json") or {}
    judge = load("evals/judge_results.json") or {}
    judge_date = datetime.fromtimestamp((ROOT / "evals" / "judge_results.json").stat().st_mtime) \
        if judge else None

    checks = [c for s in scen for c in s.get("checks", [])]
    invariants = [c for c in checks if c.get("kind") != "scenario"]
    inv_names = sorted({c["name"] for c in invariants})

    def files_ok(files: list[str]) -> bool:
        return all(tests["per_file"].get(f, 0) > 0
                   and not any(x.startswith(f + "::") for x in tests["failed"]) for f in files)

    brief_rows = []
    for section, need, sids, files in BRIEF:
        if section == "3. Evaluation":
            covered = {k: all(by_id.get(i, {}).get("passed") for i in v)
                       for k, v in CATEGORIES.items()}
            ok = len(scen) >= 20 and all(covered.values()) and len(inv_names) >= 1
            evidence = (f"{len(scen)} scenarios, {len(inv_names)} safety rules after each; "
                        f"{sum(covered.values())}/{len(covered)} required categories covered")
        else:
            ok = all(by_id.get(i, {}).get("passed") for i in sids) and files_ok(files)
            evidence = ", ".join([*sids, *(f"{f}.py" for f in files)])
        brief_rows.append({"section": section, "requirement": need, "ok": ok,
                           "evidence": evidence})
    dels = deliverables()

    live_cost = sum(r.get("cost_usd") or 0 for r in live)
    frontiers = Counter(r.get("frontier") for r in live)
    rounds = red.get("rounds", [])
    graded = [g for g in judge.get("graded", []) if isinstance(g.get("overall"), int)]
    calib = judge.get("calibration", [])
    s27 = by_id.get("S27", {})

    summary = {
        "generated": datetime.now().isoformat(timespec="minutes"),
        "steps": steps,
        "tests": {"total": tests["total"], "failed": tests["failed"],
                  "per_file": tests["per_file"]},
        "scenarios": {"total": len(scen), "passed": sum(s["passed"] for s in scen),
                      "checks": len(checks), "safety_rules": inv_names,
                      "safety_checks_run": len(invariants)},
        "live_replay": {"total": len(live), "passed": sum(r["passed"] for r in live),
                        "frontiers": len(frontiers), "recorded_cost_usd": round(live_cost, 4)},
        "red_team": rounds,
        "judge": {"model": judge.get("model"), "graded": len(graded),
                  "mean_overall": round(mean(g["overall"] for g in graded), 2) if graded else None,
                  "calibration": f"{sum(c['ok'] for c in calib)}/{len(calib)}",
                  "saved": judge_date.isoformat(timespec="minutes") if judge_date else None},
        "brief": brief_rows, "deliverables": dels,
    }
    JSON_OUT.write_text(json.dumps(summary, indent=1, ensure_ascii=False))

    mark = {True: "PASS", False: "**FAIL**", None: "manual"}
    L = ["# Evaluation report", "",
         f"Generated by `python -m evals.pipeline` on {summary['generated'].replace('T', ' ')}"
         " (offline, no model calls, $0). Every number below comes from the run; "
         "do not edit by hand.", "", "## Pipeline steps", "",
         "| Step | Command | Result | Time |", "|---|---|---|---|"]
    for s in steps:
        L.append(f"| {s['step']} | `{s['command']}` | {'PASS' if s['exit'] == 0 else '**FAIL**'}"
                 f" | {s['seconds']} s |")
    L += ["", "## Headline numbers", "",
          f"- **Tests:** {tests['total'] - len(tests['failed'])}/{tests['total']} pass across "
          f"{len(tests['per_file'])} files.",
          f"- **Scenarios:** {summary['scenarios']['passed']}/{len(scen)} pass; "
          f"{len(checks)} checks, of which {len(invariants)} are the {len(inv_names)} safety "
          "rules run after every scenario. Table: [eval_results.md](eval_results.md).",
          f"- **Live Gemini cases (recorded, re-scored offline):** "
          f"{summary['live_replay']['passed']}/{len(live)} pass across {len(frontiers)} "
          f"frontiers; recording cost ${live_cost:.2f}. Table: "
          "[live_eval_results.md](live_eval_results.md).",
          ]
    if rounds:
        last = rounds[-1]
        L.append(f"- **Red team (blind, newest round {last['round']}):** screen caught "
                 f"{last['blind']['caught']}/{last['blind']['attacks']} attacks with "
                 f"{last['blind']['false_positives']}/{last['blind']['benign']} false alarms "
                 "before any model call; the agent handled the rest "
                 "([redteam_results.md](redteam_results.md)).")
    if graded:
        L.append(f"- **Reply quality (LLM judge, saved {summary['judge']['saved'][:10]}, not "
                 f"re-run here):** {len(graded)} replies, mean "
                 f"{summary['judge']['mean_overall']}/5; judge calibration "
                 f"{summary['judge']['calibration']} ([judge_results.md](judge_results.md)).")
    if s27:
        L.append(f"- **Context cap (S27):** {s27.get('actual', '')}.")
    L += ["", "## Brief coverage (Orange assignment, sections 2–4)", "",
          "| Section | Requirement | Result | Evidence |", "|---|---|---|---|"]
    for r in brief_rows:
        L.append(f"| {r['section']} | {r['requirement']} | {mark[r['ok']]} | {r['evidence']} |")
    L += ["", "Required evaluation categories → scenarios:", ""]
    for k, v in CATEGORIES.items():
        st = all(by_id.get(i, {}).get("passed") for i in v)
        L.append(f"- {k}: {', '.join(v)} ({'pass' if st else 'FAIL'})")
    L += ["", "## Deliverables (section 5)", "", "| Deliverable | Result | Evidence |",
          "|---|---|---|"]
    for d in dels:
        L.append(f"| {d['item']} | {mark[d['ok']]} | {d['evidence']} |")
    L += ["", "## Safety rules checked after every scenario", ""]
    L += [f"- {n}" for n in inv_names]
    L += ["", "## Tests per file", "", "| File | Tests |", "|---|---|"]
    for f, n in sorted(tests["per_file"].items()):
        L.append(f"| {f}.py | {n} |")
    if tests["failed"]:
        L += ["", "## Failing tests", ""] + [f"- {x}" for x in tests["failed"]]
    REPORT.write_text("\n".join(L) + "\n")

    ok = all(s["exit"] == 0 for s in steps) and all(r["ok"] for r in brief_rows) \
        and all(d["ok"] is not False for d in dels)
    print(f"\nwrote {REPORT.relative_to(ROOT)} and {JSON_OUT.relative_to(ROOT)}")
    print(f"tests {tests['total'] - len(tests['failed'])}/{tests['total']} · scenarios "
          f"{summary['scenarios']['passed']}/{len(scen)} · live "
          f"{summary['live_replay']['passed']}/{len(live)} · brief "
          f"{sum(r['ok'] for r in brief_rows)}/{len(brief_rows)} · "
          f"{'ALL PASS' if ok else 'SOMETHING FAILED'}")
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())
